css:
.pow-att { font-size: 8px; }
.pow-hd { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; }
.pow-logo { height: 30px; }
.pow-title { font-size: 13px; font-weight: 700; letter-spacing: 0.4px; }
.pow-name { font-size: 9px; color: #555; }
.pow-meta { font-size: 8px; margin-bottom: 5px; }
.pow-meta span { margin-right: 12px; }
.pow-legend { font-size: 7.5px; background: #f3f3f3; padding: 3px 5px; margin-bottom: 6px; }

/* One header bar per Sale Item, carrying the item type(s) after the code. */
.pow-grp { background: #eaeaea; padding: 3px 5px; font-size: 8px; margin-top: 8px; }
.pow-grp-count { float: right; opacity: 0.85; }

.pow-grid { width: 100%; border-collapse: collapse; table-layout: fixed; }
/* Repeat the header on every page but keep wkhtmltopdf from overlapping tall rows. */
.pow-grid thead { display: table-row-group; }
.pow-grid th, .pow-grid td {
	border: 1px solid #bbb; padding: 1px 2px; font-size: 7px;
	text-align: center; vertical-align: middle; word-wrap: break-word;
}
.pow-grid th { background: #f7f7f7; font-weight: 600; }
.pow-grid .c-id, .pow-grid .c-name { text-align: left; }
.pow-grid .c-name { width: 90px; }
.pow-grid .c-id { width: 62px; }
.pow-grid .c-num { width: 34px; }
.pow-grid .pow-total td { font-weight: 700; background: #f7f7f7; }
.empty { text-align: center; color: #777; padding: 6px; font-style: italic; }
